return $$$OK

 Do %page.%SetValueById("namespLbl","ITFCOMMON")
 Do %page.%SetValueById("userLbl",$USERNAME)
 Do %page.%SetValueById("systemLbl", $SYSTEM)

  try {
	Set img = %page.%GetComponentById("TemplateLogo")
    Set stream=##class(%FileBinaryStream).%New()

    if $$$ISOK(stream.LinkToFile("/WORK/common/images/intermountain.jpg"))
    {
     Set oid=stream.%Oid()
     Set img.streamId = oid 
   }
 } catch err
 {
 }
 return $$$OK

var srcFields = zenPage.getComponentById('srcFields').getValue();

sessionGrp = zenPage.getComponentById('sessionRange');
dtGrp = zenPage.getComponentById('dtRange');
if(srcFields == "Date")
{
	sessionGrp.setProperty('hidden', true);
	dtGrp.setProperty('hidden', false);
}
else
{
	sessionGrp.setProperty('hidden', false);
	dtGrp.setProperty('hidden', true);

}

	zenPage.getComponentById('lblAccess').setValue('Confirming');

   		var nmSp = zenPage.getComponentById('namespace').getValue();
	   	var srcComponent = zenPage.getComponentById('srcComponent').getValue();
	    var dstComponent = zenPage.getComponentById('dstComponent').getValue();
	    var errStr = zenPage.getComponentById('errStr').getValue();
	    var srcCondition = zenPage.getComponentById('srcCondition').getValue();
	    var dtSearch = zenPage.getComponentById('srcFields').getValue();
	    if( dtSearch == "Date")
	    {
	    	var rangeVal1 = zenPage.getComponentById('stDtTm1').getValue();
	    	var rangeVal2 = zenPage.getComponentById('stDtTm2').getValue();
	    }
	    else
	    {
		   	var rangeVal1 = zenPage.getComponentById('stSessionId').getValue();
	    	var rangeVal2 = zenPage.getComponentById('endSessionId').getValue();

	    }
	    var rsndTest = zenPage.getComponentById('rsndTest').getValue();
	    var rsndOrig = zenPage.getComponentById('rsndOrig').getValue();

	    if(nmSp == '' || srcComponent == '' || dstComponent == '' || errStr == '' || rangeVal1 == '' || rangeVal2 == '')
	    {

			    var missingFlds = 'Required fileds are missing' 
			    if(nmSp == '')
			     missingFlds = "Namespace " 
			     if( srcComponent == '' ) missingFlds  = missingFlds + ', Source '
			     if( dstComponent == '' ) missingFlds =  missingFlds + ', Destination '
			     if( errStr == '' ) missingFlds =  missingFlds + ', Search string '
			     if( rangeVal1 == '' ) missingFlds =  missingFlds + ', Starting value '
			     if( rangeVal2 == '') missingFlds =  missingFlds + ', Ending value '
			     zenPage.getComponentById('lblAccess').setValue(missingFlds )
		}
		else
		{
			var statStr = zenPage.GetNumRows(nmSp, srcComponent, dstComponent, srcCondition, errStr, dtSearch, rangeVal1, rangeVal2, rsndOrig)
	    	if (statStr.length > 0) 
		    { 
				  var group = this.createComponent('modalGroup'); 
			      group.setProperty('height', 100);
			      zenPage.addChild(group);

			      var lbl = this.createComponent('label'); 
			      group.addChild(lbl); 		      
			      lbl.setProperty('value', statStr)


			      var sp2 = this.createComponent('spacer');
			      sp2.setProperty('height', 10); 
			      group.addChild(sp2);


			      var sp1 = this.createComponent('spacer'); 
			      sp1.setProperty('height', 10);
			      group.addChild(sp1);

			      var hg = this.createComponent('hgroup'); 
			      group.addChild(hg); 
			      hg.setProperty('cellAlign', 'center')

			      var btn = this.createComponent('button'); 
			      hg.addChild(btn); 
			      btn.setProperty('caption','Cancel'); 
			      btn.setProperty('onclick','zenPage.btnCancel();'); 

			       var sp3 = this.createComponent('spacer'); 
			      hg.addChild(sp3);

			      sp3.setProperty('width', 50);
			      if (statStr.indexOf("SessionId(s): 0") < 0)
			      {
			      	var btn2 = this.createComponent('button'); 
			      	hg.addChild(btn2); 
			      	if(rsndTest)
			      		btn2.setProperty('caption','Get IDs');
			      	else
			      	 	btn2.setProperty('caption','Resend');
			      	btn2.setProperty('onclick','zenPage.btnOk();'); 
			      }

			      zenPage.refreshContents(true); 

			      group.show('Confirm', 'dynamic');
		    }
		}

   var nmSp = zenPage.getComponentById('namespace').getValue();
	   	var srcComponent = zenPage.getComponentById('srcComponent').getValue();
	    var dstComponent = zenPage.getComponentById('dstComponent').getValue();
	    var errStr = zenPage.getComponentById('errStr').getValue();
	    var srcCondition = zenPage.getComponentById('srcCondition').getValue();

	    var rsndTest = zenPage.getComponentById('rsndTest').getValue();
	    var rsndOrig = zenPage.getComponentById('rsndOrig').getValue();
	    var headQ = zenPage.getComponentById('headQ').getValue();
	    var dtSearch = zenPage.getComponentById('srcFields').getValue();

	    if( dtSearch == "Date")
	    {
	    	var rangeVal1 = zenPage.getComponentById('stDtTm1').getValue();
	    	var rangeVal2 = zenPage.getComponentById('stDtTm2').getValue();
	    }
	    else
	    {
		   	var rangeVal1 = zenPage.getComponentById('stSessionId').getValue();
	    	var rangeVal2 = zenPage.getComponentById('endSessionId').getValue();

	    }

		zenPage.getComponentById('lblAccess').setValue('Resending');
    	zenPage.endModal();
	    try
	    {	

	    	var statStr = zenPage.Resend(rsndTest, nmSp, srcComponent, dstComponent,  srcCondition, errStr, dtSearch, rangeVal1, rangeVal2, rsndOrig, headQ)

	    	zenPage.getComponentById('lblAccess').setValue(statStr);
	    	return;




	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
	    }


	set retStr = ""
	set $NAMESPACE = nmSp
	set numRows = 0

	if (cond = "like")

	{
		set errStr = "%" _ errStr _ "%"
	}

	try {
	set myquery = 5
	set myquery(1) = "Select count(distinct mh.SessionId) As IdCnt from Ens.MessageHeader mh, Ens_Util.Log log "
	set myquery(2) = "where mh.Type = 1 and log.ConfigName =  ?  and mh.SourceConfigName = ?" // mh.Type = 'Request'
	if (rsndOrig = "true")
	{
		set myquery(3) = " and Description not like 'RESENT%' and mh.TargetConfigName = log.ConfigName and log.sessionId = mh.sessionId and "
	} 
	else
	{
		set myquery(3) = " and mh.TargetConfigName = log.ConfigName and log.sessionId = mh.sessionId and "
	}
	set myquery(4) = " log.Text " _ cond _ " ?"
	set val1 = rangeVal1
	set val2 = rangeVal2 	
	set myquery(5) = " and mh.SessionId BETWEEN ? AND ?"


	if (dtSearch = "Date")
	{	
		set $NAMESPACE = nmSp
		SET zonesave=480 // $SYSTEM.SYS.TimeZone()
	 	set $ZTIMEZONE = 0
		set h1 = $ZDATETIMEH(rangeVal1, 3, 1)
		set h2 = $ZDATETIMEH(rangeVal2, 3, 1)
		//Data is stored in DB as GMT
	 	set $ZTIMEZONE = zonesave
	 	set hDtTm1 = $SYSTEM.Util.LocalWithZTIMEZONEtoUTC(h1)
	 	set hDtTm2 = $SYSTEM.Util.LocalWithZTIMEZONEtoUTC(h2)
	 	set val1 =	$ZDATETIME(hDtTm1, 3, 1)
	 	set val2 = $ZDATETIME(hDtTm2, 3, 1)

    	set myquery(5) = " and log.TimeLogged BETWEEN ? AND ?"
	}


	SET tStatement = ##class(%SQL.Statement).%New()
  	SET qStatus = tStatement.%Prepare(.myquery)
    IF qStatus'=1 { set retStr = retStr _  "%Prepare failed:" _ qStatus return retStr}

  	SET rset = tStatement.%Execute(dstComponent, srcComponent, errStr, val1, val2)

  	IF rset.%SQLCODE=0 { set retStr = retStr _ ", Created a query" }
  	ELSEIF rset.%SQLCODE=-361 { set retStr = retStr _ ", Query exists: " _ rset.%Message }
  	ELSE { set retStr = retStr _ ", CREATE QUERY error: " _ rset.%SQLCODE_", "_rset.%Message   return retStr}


   WHILE rset.%Next() {

     set numRows = rset.IdCnt

   }
   SET sc=rset.Close()


	Set retStr =  "# of SessionId(s): " _ numRows _ ".<BR> namespace: " _ $NAMESPACE 

	FOR i=1:1:5
	{
	 Set retStr = retStr _ "<BR> " _ myquery(i) 
	}
	Set retStr = retStr _ "<BR> Parameters:  " _ dstComponent _", "_ srcComponent _", "_ errStr _", "_ val1 _", "_ val2

	} catch(err)
	{
		set retStr = retStr _ err.AsStatus() _ " Could not run SQL "_ rangeVal1 _": " _ rangeVal2
	}

	Return retStr

 try {
	 set $NAMESPACE = nmSp
	 if (rsndTest = "true")
		{
			set retStr = "Get Ids for resend " _ destComp
		}
		else
		{
			set retStr = "Resend from " _ srcComp
		}

	 SET myquery = 7 
	 SET myquery(1) = " select distinct mh.Id AS tMsgId "
	 SET myquery(2) = " from  Ens.MessageHeader mh, Ens_Util.Log  log "
	 SET myquery(3) = " where mh.Type = 1 and log.ConfigName =  ? "   // mh.Type = 'Request'
	 SET myquery(4) = " and log.Text " _ cond _  " ?  "

	 if (rsndOrig = "true" )
	{
		SET myquery(5) = " and Description not like 'RESENT%' and mh.TargetConfigName = log.ConfigName and log.sessionId = mh.sessionId "
	}
	else
	{
		SET myquery(5) = " and mh.TargetConfigName = log.ConfigName and log.sessionId = mh.sessionId "
	}

	 SET myquery(6) = " and mh.SourceConfigName = ? AND TargetConfigName = ?"
	 if (dtSearch = "Date")
	 {
	 	SET myquery(7) = " and log.TimeLogged BETWEEN ? AND ? "

	 	SET zonesave=480 // $SYSTEM.SYS.TimeZone()
	 	set $ZTIMEZONE = 0
		set h1 = $ZDATETIMEH(rangeVal1, 3, 1)
		set h2 = $ZDATETIMEH(rangeVal2, 3, 1)
		//Data is stored in DB as GMT
	 	set $ZTIMEZONE = zonesave
	 	set hDtTm1 = $SYSTEM.Util.LocalWithZTIMEZONEtoUTC(h1)
	 	set hDtTm2 = $SYSTEM.Util.LocalWithZTIMEZONEtoUTC(h2)
	 	set val1 =	$ZDATETIME(hDtTm1, 3, 1)
	 	set val2 = $ZDATETIME(hDtTm2, 3, 1)
	 }
	 else
	 {
 	 	SET myquery(7)  = " and mh.SessionId BETWEEN ? AND ?"
 	 	set val1 = rangeVal1
		set val2 = rangeVal2 	
	 }

 	if (cond = "like")
	{

		set errStr = "%" _ errStr _ "%"
	}


  SET tStatement = ##class(%SQL.Statement).%New()
  SET qStatus = tStatement.%Prepare(.myquery)
    IF qStatus'=1 {
	    set retStr =  retStr _ ", %Prepare failed:" DO $System.Status.DisplayError(qStatus) return retStr _ qStatus}

  SET rset = tStatement.%Execute(destComp, errStr, srcComp, destComp, val1, val2)
  IF rset.%SQLCODE=0 { set retStr =  retStr _ "<BR> Executed a query successfully: <I>" _ errStr _", " _ srcComp_", " _  destComp_", " _  val1 _", " _  val2 _ "</I>"}
  ELSEIF rset.%SQLCODE=-361 { $$$LOGERROR("Query exists: " _ rset.%Message) }
  ELSE { set retStr =  retStr _ ", CREATE QUERY error: " _ rset.%SQLCODE_", "_rset.%Message   return retStr}

  set arrInd = 0
  Set tMsgIdArr = ""

   WHILE rset.%Next() {
	 set arrInd = arrInd + 1
     set tMsgId = rset.tMsgId

     Set tMsgIdArr(arrInd) = tMsgId

   }
   SET sc=rset.Close()
   set retStr =  retStr _  " <BR> # of MessageHeader IDs: " _ arrInd  _ ", " _ dtSearch
	 set HeadOfQueue = 0
	 if (headQ = "true")
		{
			set HeadOfQueue = 1
		}
	 set Key  = "KEY"
	 set num = 0
	 set msgId = "" 

		 Do {
	        Set msgId=$Order(tMsgIdArr(msgId)) Quit:msgId="" ;get the next S1 subscript

	        Set tMsgId = tMsgIdArr(msgId)


		    if (rsndTest = 0)
	 		{	

				Set tSC=##class(Ens.MessageHeader).ResendDuplicatedMessage(tMsgId,.tNewHeaderId,destComp,,,HeadOfQueue)
				If ($$$ISERR(tSC)) {
					Set errText = $System.Status.GetErrorText(tSC)
					set retStr =  retStr _  "<BR> - " _ num _ "Error: " _ errText _ ", Ens.MessageHeader.Id: " _ tMsgId	
					set qStatus = $$$ERROR(	errText)		
				}

				Else {
					set num = num + 1
					set retStr =  retStr _  "<BR> - " _ num _ ". RESENT: Ens.MessageHeader.Id: " _ tMsgId _ ", New Id: " _ tNewHeaderId 
					Set ^CacheTemp.ResendIDs(Key,tMsgId,"sc") = "OK"
					Set ^CacheTemp.ResendIDs(Key,tMsgId,"new") = tNewHeaderId
				}
	 		}
	 		else
	 		{
		 		set retStr =  retStr _  "<BR> - Ens.MessageHeader.Id: " _ tMsgId
		 		set num = num + 1
	 		}


	  	} While msgId'=""

  		if (rsndTest = 0)
	 	{
  			Set retStr =  retStr _ "<BR><BR> <B>Resent " _ num _ " messages to: " _ destComp _ "</B>"
	 	}
   } catch(err)
	    {
		    set retStr = "Exception: " _ err.message
		    // clearInterval(this);
		    // zenSynchronousMode = true;
	    }
	return retStr

	zenPage.getComponentById('lblAccess').setValue('Verifying');
   var comp = zenPage.getComponentById('verComponent').getValue();
   var nmSp = zenPage.getComponentById('verNamespace').getValue();

    if(comp != '' && nmSp != '')
    {
	   try
	    {
			   zenSynchronousMode = false;
			  var group = this.createComponent('modalGroup'); 
		      group.setProperty('height', 100);
		      zenPage.addChild(group);

		      var lbl = this.createComponent('label'); 
		      group.addChild(lbl); 
		      lbl.setProperty('value','Please Wait, Verifying: ' + comp)
				zenPage.refreshContents(true); 
		    	group.show('Verify', 'dynamic');

		     	zenPage.getComponentById('lblAccess').setProperty('hidden', false);
		     	timerVar = setInterval(function(){ zenPage.VerifyTimer('Verifying')}, 1000);

		   		zenPage.CallVerifyService(comp, nmSp);


	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
		    clearInterval(this);
		    zenSynchronousMode = true;
	    }

    }
    else
    {
	    zenPage.getComponentById('lblAccess').setValue('Component name and Namespace are Required fileds')
    }

   try
	    {
		    if( zenPage.getComponentById('lblAccess').getValue().substr(0, srcTxt.length)  != srcTxt)
  			{
	  			clearInterval(timerVar);  
	  			if (zenPage.modalStack != null && zenPage.modalStack.length>0)
	  			{
	  				zenPage.endModal();		
	  			}		
   				zenSynchronousMode = true;   			  				 
  			}
  			else
  			{
	  			zenPage.getComponentById('lblAccess').setValue(zenPage.getComponentById('lblAccess').getValue() + ".");
  			}


} catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception in VerifyTimer: ' + err.message);
		    clearInterval(timerVar);
		    zenSynchronousMode = true;
	    }
